package vn.tuan.service;
import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.beans.factory.annotation.Value;import org.springframework.transaction.annotation.Transactional;import vn.tuan.entity.Order;import vn.tuan.repository.OrderRepository;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.math.*;
@Service @RequiredArgsConstructor public class PaymentService {
 private final OrderRepository orders;private final OrderEvents events;
 @Value("${app.vnpay.enabled:false}")boolean enabled;@Value("${app.vnpay.tmn-code:}")String tmn;@Value("${app.vnpay.hash-secret:}")String secret;@Value("${app.vnpay.url:https://sandbox.vnpayment.vn/paymentv2/vpcpay.html}")String url;@Value("${app.vnpay.return-url:http://localhost:8080/payment/return}")String returnUrl;
 public boolean available(){return enabled && !tmn.isBlank() && !secret.isBlank();}
 public String redirect(Order o,String ip){OrderRules.require(available(),"Chưa cấu hình VNPAY");var time=ZonedDateTime.now(ZoneId.of("Asia/Ho_Chi_Minh"));var fmt=DateTimeFormatter.ofPattern("yyyyMMddHHmmss");Map<String,String> p=new TreeMap<>();p.put("vnp_Version","2.1.0");p.put("vnp_Command","pay");p.put("vnp_TmnCode",tmn);p.put("vnp_Amount",o.getFinalAmount().multiply(BigDecimal.valueOf(100)).toBigIntegerExact().toString());p.put("vnp_CurrCode","VND");p.put("vnp_TxnRef",o.getPaymentReference());p.put("vnp_OrderInfo","Thanh toan UTETra "+o.getId());p.put("vnp_OrderType","other");p.put("vnp_Locale","vn");p.put("vnp_ReturnUrl",returnUrl);p.put("vnp_IpAddr",ip);p.put("vnp_CreateDate",time.format(fmt));p.put("vnp_ExpireDate",time.plusMinutes(15).format(fmt));String query=PaymentSigner.query(p);return url+"?"+query+"&vnp_SecureHash="+PaymentSigner.sign(secret,query);}
 public boolean valid(Map<String,String> p){return available() && tmn.equals(p.get("vnp_TmnCode")) && PaymentSigner.verify(secret,p);}
 @Transactional public Map<String,String> ipn(Map<String,String> p){if(!valid(p))return reply("97","Invalid signature");var found=orders.findByPaymentReference(p.get("vnp_TxnRef"));if(found.isEmpty())return reply("01","Order not found");Order o=orders.lockById(found.get().getId()).orElseThrow();if(!"VNPAY".equals(o.getPaymentMethod()))return reply("01","Invalid order");String amount=o.getFinalAmount().multiply(BigDecimal.valueOf(100)).toBigIntegerExact().toString();if(!amount.equals(p.get("vnp_Amount")))return reply("04","Invalid amount");if("PAID".equals(o.getPaymentStatus()) || "REFUND_PENDING".equals(o.getPaymentStatus()) || "REFUNDED".equals(o.getPaymentStatus()))return reply("02","Already confirmed");
 boolean success="00".equals(p.get("vnp_ResponseCode")) && "00".equals(p.get("vnp_TransactionStatus"));
 if(success){o.setGatewayTransactionId(p.get("vnp_TransactionNo"));if("CANCELLED".equals(o.getStatus()))o.setPaymentStatus("REFUND_PENDING");else o.setPaymentStatus("PAID");}else o.setPaymentStatus("FAILED");events.changed(o);return reply("00","Confirm success");}
 private Map<String,String> reply(String code,String message){return Map.of("RspCode",code,"Message",message);}
}
